<script setup>
import Layout from '../../Components/Layout.vue'; import Icon from '../../Components/Icon.vue'; import {useForm,Link,router,usePage} from '@inertiajs/vue3'
const props=defineProps({project:Object}); const role=usePage().props.auth.user.role; const canEdit=['admin','team'].includes(role)
const task=useForm({title:'',description:'',status:'todo',priority:'medium',due_date:''}); const update=useForm({body:''}); const file=useForm({file:null});
const addTask=()=>task.post(`/projects/${props.project.id}/tasks`,{onSuccess:()=>task.reset()}); const addUpdate=()=>update.post(`/projects/${props.project.id}/updates`,{onSuccess:()=>update.reset()}); const upload=()=>file.post(`/projects/${props.project.id}/files`,{forceFormData:true,onSuccess:()=>file.reset()}); const del=()=>{if(confirm('Delete this project?'))router.delete(`/projects/${props.project.id}`)}; const changeStatus=(id,status)=>router.put(`/tasks/${id}`,{status},{preserveScroll:true})
</script>
<template><Layout><div class="detail-head"><div><Link href="/projects" class="back-link">← Projects</Link><h1>{{project.name}}</h1><p>{{project.tenant}} · {{project.status}} · Due {{project.due_date||'No date'}}</p></div><button v-if="role==='admin'" class="danger-btn" @click="del">Delete project</button></div><div class="detail-grid"><div class="panel"><div class="panel-head"><div><span class="eyebrow">DELIVERY BOARD</span><h2>Tasks</h2></div><span class="queue-count">{{project.tasks.length}} tasks</span></div><div class="task-list compact"><div v-for="t in project.tasks" :key="t.id" class="task-card"><div class="task-body"><div class="task-row"><strong>{{t.title}}</strong><span class="priority" :class="t.priority==='high'?'danger':t.priority==='medium'?'warning':'neutral'">{{t.priority}}</span></div><div class="task-foot"><span>{{t.due_date||'No due date'}}</span><select :value="t.status" :disabled="!canEdit" @change="changeStatus(t.id,$event.target.value)"><option value="todo">To do</option><option value="in_progress">In progress</option><option value="done">Done</option></select></div></div></div></div><form v-if="canEdit" @submit.prevent="addTask" class="inline-form"><input v-model="task.title" placeholder="Add a task…"><select v-model="task.priority"><option>low</option><option>medium</option><option>high</option></select><button class="primary-btn"><Icon name="plus" :size="16"/> Add</button></form></div><div class="panel"><div class="panel-head"><div><span class="eyebrow">PROJECT INFO</span><h2>Overview</h2></div></div><p class="detail-description">{{project.description || 'No description provided.'}}</p><div class="info-stack"><div><span>Status</span><strong>{{project.status}}</strong></div><div><span>Due date</span><strong>{{project.due_date || 'No date'}}</strong></div><div><span>Tenant</span><strong>{{project.tenant}}</strong></div></div><h3 class="section-label">Files</h3><div v-for="f in project.files" :key="f.id" class="file-row"><Icon name="file" :size="17"/><a :href="`/project-files/${f.id}/download`">{{f.name}}</a><small>{{f.mime_type}}</small></div><form v-if="canEdit" @submit.prevent="upload" class="upload-form"><input type="file" @change="file.file=$event.target.files[0]"><button class="secondary-btn">Upload</button></form></div><div class="panel updates-panel"><div class="panel-head"><div><span class="eyebrow">COMMUNICATION</span><h2>Updates</h2></div></div><div v-for="u in project.updates" :key="u.id" class="feed-item"><div class="feed-dot"></div><div><strong>{{u.author}}</strong><p>{{u.body}}</p><small>{{u.created_at}}</small></div></div><form @submit.prevent="addUpdate" class="update-form"><textarea v-model="update.body" placeholder="Share a project update…"></textarea><button class="primary-btn">Post update</button></form></div></div></Layout></template>
